import { memo, Profiler, useRef } from "react";

type ChildProps = { onClick: (label: string) => void };

// The child is memo()-wrapped, so it should skip re-rendering while its props are
// shallow-equal. Do NOT edit this file — the fix belongs in Parent.tsx.
export const Child = memo(function Child({ onClick }: ChildProps) {
  // How the count works (not part of the fix): React calls a <Profiler>'s `onRender` once
  // per committed render of the tree inside it. That works in development builds, which
  // the preview and the tests both run. A `renders.current += 1` in the render body would
  // count twice per render under the preview's StrictMode. `onRender` runs after React has
  // updated the DOM, so it writes the number straight into the <span>, which React
  // renders empty and never touches.
  const renders = useRef(0);
  const output = useRef<HTMLSpanElement>(null);
  function countRender() {
    renders.current += 1;
    if (output.current) output.current.textContent = String(renders.current);
  }

  return (
    <Profiler id="Child" onRender={countRender}>
      <div>
        <p>
          child renders: <span data-testid="child-renders" ref={output} />
        </p>
        <button onClick={() => onClick("child")}>Child action</button>
      </div>
    </Profiler>
  );
});
